using Amazon.Runtime;
using Amazon.Runtime.Internal;
using Amazon.S3;

// Configure global retry behavior
AWSConfigs.HttpClientMaxConnectionsPerServer = 10;
AWSConfigs.LoggingConfig.LogTo = LoggingOptions.Console;
AWSConfigs.LoggingConfig.LogResponses = ResponseLoggingOption.OnError;

// Create a client with custom config
AmazonS3Config config = new AmazonS3Config
{
    RegionEndpoint = RegionEndpoint.USEast1,
    MaxErrorRetry = 5,
    Timeout = TimeSpan.FromSeconds(30)
};

AmazonS3Client client = new AmazonS3Client("key", "secret", config);
